import { SynapseEnhancedError } from "./http.ts";
import { ErrorCode } from "./error-codes.ts";

export interface RetryPolicyOptions {
    maxAttempts?: number;
    initialDelay?: number;
    maxDelay?: number;
    backoffMultiplier?: number;
    jitterFactor?: number;
    timeout?: number;
}

function getSecureRandom(): number {
    const array = new Uint32Array(1);
    crypto.getRandomValues(array);
    return array[0] / (0xffffffff + 1);
}

export class RetryPolicy {
    private readonly maxAttempts: number;
    private readonly initialDelay: number;
    private readonly maxDelay: number;
    private readonly backoffMultiplier: number;
    private readonly jitterFactor: number;
    private readonly timeout: number;

    public constructor(options?: RetryPolicyOptions);
    public constructor(maxAttempts?: number, initialDelay?: number, maxDelay?: number, timeout?: number);
    /**
     * Creates a new retry policy instance
     */
    public constructor(
        maxAttemptsOrOptions?: number | RetryPolicyOptions,
        initialDelay?: number,
        maxDelay?: number,
        timeout?: number,
    ) {
        if (typeof maxAttemptsOrOptions === "number") {
            this.maxAttempts = maxAttemptsOrOptions ?? 3;
            this.initialDelay = initialDelay ?? 1000;
            this.maxDelay = maxDelay ?? 30000;
            this.backoffMultiplier = 2;
            this.jitterFactor = 0.1;
            this.timeout = timeout ?? 30000;
        } else {
            const options = maxAttemptsOrOptions ?? {};
            this.maxAttempts = options.maxAttempts ?? 3;
            this.initialDelay = options.initialDelay ?? 1000;
            this.maxDelay = options.maxDelay ?? 30000;
            this.backoffMultiplier = options.backoffMultiplier ?? 2;
            this.jitterFactor = options.jitterFactor ?? 0.1;
            this.timeout = options.timeout ?? 30000;
        }
    }

    public shouldRetry(error: SynapseEnhancedError): boolean {
        return error.retryable;
    }

    public getDelay(attempt: number): number {
        const delay = Math.min(this.initialDelay * Math.pow(this.backoffMultiplier, attempt), this.maxDelay);
        const jitter = delay * this.jitterFactor * getSecureRandom();
        return Math.min(delay + jitter, this.maxDelay);
    }

    public async execute<T>(
        operation: () => Promise<T>,
        isRetryable?: (error: SynapseEnhancedError) => boolean,
    ): Promise<T> {
        let lastError: SynapseEnhancedError | null = null;

        for (let attempt = 0; attempt < this.maxAttempts; attempt++) {
            try {
                return await this.withTimeout(operation());
            } catch (error) {
                if (!(error instanceof SynapseEnhancedError)) {
                    throw error;
                }

                const retryable = isRetryable ? isRetryable(error) : this.shouldRetry(error);

                if (!retryable || attempt === this.maxAttempts - 1) {
                    throw error;
                }

                lastError = error;
                await this.delay(attempt);
            }
        }

        throw lastError;
    }

    /**
     * Wraps a promise with a timeout mechanism
     * @param promise - The promise to wrap
     * @returns Promise that rejects if timeout is exceeded
     */
    private async withTimeout<T>(promise: Promise<T>): Promise<T> {
        return new Promise((resolve, reject) => {
            const timer = setTimeout(() => {
                reject(new SynapseEnhancedError("Request timed out", ErrorCode.TIMEOUT));
            }, this.timeout);

            promise.then(resolve, reject).finally(() => {
                clearTimeout(timer);
            });
        });
    }

    /**
     * Calculates delay for a specific retry attempt using exponential backoff with jitter
     * @param attempt - Current attempt number (0-indexed)
     * @returns Delay in milliseconds before next retry
     */
    private delay(attempt: number): Promise<void> {
        return new Promise((resolve) => setTimeout(resolve, this.getDelay(attempt)));
    }
}

export function isRetryableError(error: unknown): boolean {
    if (error instanceof SynapseEnhancedError) {
        return error.retryable;
    }
    if (error instanceof Error) {
        if (error.name === "AbortError" || error.name === "TimeoutError") {
            return true;
        }
    }
    return false;
}

export interface RetryResult<T> {
    success: boolean;
    data?: T;
    attempts: number;
    error?: SynapseEnhancedError;
}

export async function withRetry<T>(
    operation: () => Promise<T>,
    policy?: RetryPolicy,
    signal?: AbortSignal,
): Promise<RetryResult<T>> {
    const actualPolicy = policy ?? new RetryPolicy();
    let attempts = 0;
    let lastError: SynapseEnhancedError | undefined;

    for (let attempt = 0; attempt < actualPolicy["maxAttempts"]; attempt++) {
        attempts++;

        if (signal?.aborted) {
            return {
                success: false,
                attempts,
                error: new SynapseEnhancedError("Request cancelled", ErrorCode.CANCELLED),
            };
        }

        try {
            const data = await operation();
            return {
                success: true,
                data,
                attempts,
            };
        } catch (error) {
            if (error instanceof SynapseEnhancedError) {
                lastError = error;
                if (!actualPolicy.shouldRetry(error) || attempt === actualPolicy["maxAttempts"] - 1) {
                    return {
                        success: false,
                        attempts,
                        error,
                    };
                }
                await new Promise((resolve) => setTimeout(resolve, actualPolicy.getDelay(attempt)));
            } else {
                return {
                    success: false,
                    attempts,
                    error: new SynapseEnhancedError(
                        error instanceof Error ? error.message : "Unknown error",
                        ErrorCode.UNKNOWN,
                    ),
                };
            }
        }
    }

    return {
        success: false,
        attempts,
        error: lastError ?? new SynapseEnhancedError("Max retries exceeded", ErrorCode.TIMEOUT),
    };
}
